create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text,created_at timestamptz default now());create table if not exists public.health_entries(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,concern text not null,notes text,entry_date date not null default current_date,created_at timestamptz default now());alter table public.profiles enable row level security;alter table public.health_entries enable row level security;create policy "Users manage own profile" on public.profiles for all using(auth.uid()=id) with check(auth.uid()=id);create policy "Users manage own health entries" on public.health_entries for all using(auth.uid()=user_id) with check(auth.uid()=user_id);